"use client";
import { Alert, AlertTitle, AlertAction } from "@ui/alert";
import { useEffect, useRef, useState } from "react";
import { Badge } from "@ui/badge";
import { Button } from "@ui/button";
import { Container, ContainerBody, ContainerFooter, ContainerHeader } from "@ui/container";
import { Empty, EmptyDescription } from "@ui/empty";
import { InlineNotice, InlineNoticeContent } from "@ui/inline-notice";
import { MetricCard } from "@ui/metric-card";
import { Select, SelectContent, SelectItem, SelectTrigger } from "@ui/select";
import { Skeleton } from "@ui/skeleton";
import { TabItem, TabPanel, Tabs, TabsList } from "@ui/tabs";
import { Tooltip } from "@ui/tooltip";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { SecurityScore, SecurityTrend } from "./security-overview-charts";
import { securityCountTotal, securityFormatCount, securityFormatDate, securityFormatNumber, securityOverviewLabels, securityValidCount, securityValidNumber } from "./security-overview-data";
import { SecurityAssets, SecurityFindings, SecurityPosture } from "./security-overview-views";
import type { SecurityOverviewProps, SecurityOverviewView } from "./security-overview-types";
const views: SecurityOverviewView[] = ["trend", "findings", "posture", "assets"];
const idleScan = { status: "idle" } as const;
/** Scope changes reset only local view and event guards; the caller owns requests and snapshots. */
export function SecurityOverview(props: SecurityOverviewProps) {
    return <SecurityOverviewContent key={props.scopeId} {...props}/>;
}
function SecurityOverviewContent({ scopeId, data, state = "ready", statusMessage, range, onRangeChange, view, defaultView = "trend", onViewChange, scan = idleScan, scanDisabledReason, exportState = "idle", exportError, actions, title, description, labels: overrides, locale = "zh-CN", timeZone = "Asia/Shanghai", className, ...props }: SecurityOverviewProps) {
    const labels = { ...securityOverviewLabels, ...overrides };
    const [localView, setLocalView] = useState(defaultView);
    const scanGuard = useRef(false);
    const exportGuard = useRef(false);
    const Shield = useIcon("shield");
    const Close = useIcon("x");
    const Calendar = useIcon("calendar");
    const Download = useIcon("arrow-down");
    const Clock = useIcon("clock");
    const scoped = data?.scopeId === scopeId ? data : null;
    const sameRange = scoped?.range === range;
    const matching = sameRange ? scoped : null;
    const loading = state === "loading" || (state !== "error" && scoped !== null && !sameRange);
    const usable = state !== "loading" && state !== "error" ? matching : null;
    const activeView = views.includes(view ?? localView) ? view ?? localView : "trend";
    const busy = scan.status === "starting" || scan.status === "running" || scan.status === "refreshing";
    // A succeeded task is not visually complete until its result belongs to the visible snapshot.
    const awaitingResult = scan.status === "succeeded" && scan.snapshotId !== scoped?.id;
    const scanning = busy || awaitingResult;
    const scoreData = state !== "error" && (state !== "loading" || scanning) ? scoped : null;
    const total = scoreData ? securityCountTotal(scoreData.openBySeverity) : null;
    const progress = scan.status === "running" && securityValidCount(scan.completed) && securityValidCount(scan.total) && scan.total > 0 && scan.completed <= scan.total ? `${scan.completed} / ${scan.total}` : null;
    const currentScore = scoreData && securityValidNumber(scoreData.score, 100) ? scoreData.score : null;
    const delta = currentScore !== null && usable && securityValidNumber(usable.previousScore, 100) ? currentScore - usable.previousScore : null;
    const scanText = scan.status === "starting" ? labels.starting : scan.status === "running" ? `${labels.scanning}${progress ? ` · ${progress}` : ""}` : scan.status === "refreshing" || awaitingResult ? labels.refreshing : scan.status === "failed" ? scan.message : scan.status === "succeeded" ? `${labels.scanComplete} · ${securityFormatNumber(scan.newFindingCount, locale)} ${labels.newFindings}` : null;
    useEffect(() => { if (!scanning)
        scanGuard.current = false; }, [scan.status, scanning]);
    useEffect(() => { if (exportState !== "pending")
        exportGuard.current = false; }, [exportState]);
    function runScan() {
        if (scanGuard.current || scanning || scanDisabledReason || !actions?.onRunScan)
            return;
        scanGuard.current = true;
        try {
            actions.onRunScan({ scopeId });
        }
        finally {
            queueMicrotask(() => { scanGuard.current = false; });
        }
    }
    function exportSnapshot() {
        if (exportGuard.current || exportState === "pending" || !usable || !actions?.onExport)
            return;
        exportGuard.current = true;
        try {
            actions.onExport({ scopeId, snapshotId: usable.id, range: usable.range });
        }
        finally {
            queueMicrotask(() => { exportGuard.current = false; });
        }
    }
    const rangeLabels = { "7d": labels.days7, "30d": labels.days30, "90d": labels.days90 };
    const metricState = loading ? "loading" : state === "error" ? "error" : "ready";
    const fixHours = usable?.medianFixTimeHours ?? null;
    const fixDays = securityValidNumber(fixHours) && fixHours >= 24;
    const viewProps = usable ? { data: usable, labels, locale, timeZone, actions } : null;
    return <Container {...props} data-block="security-overview" data-state={state} aria-busy={loading || undefined} className={cn("@container w-full max-w-xl", className)}>
    <ContainerHeader className="py-1.5">
      <div className="flex min-w-0 items-center gap-2"><h2 className="break-words text-body font-medium text-fg-default">{title ?? labels.title}</h2><Tooltip content={description ?? labels.description}><Button iconOnly size="xs" variant="ghost" aria-label={description ?? labels.description}><Shield aria-hidden/></Button></Tooltip></div>
      <div className="flex max-w-full items-center gap-2"><Select value={range} onValueChange={(value) => { if (value === "7d" || value === "30d" || value === "90d")
        onRangeChange(value); }} size="sm"><SelectTrigger icon={Calendar} aria-label={labels.range} wrapperClassName="max-w-full"/><SelectContent>{(["7d", "30d", "90d"] as const).map((value) => <SelectItem key={value} value={value} label={rangeLabels[value]}>{rangeLabels[value]}</SelectItem>)}</SelectContent></Select>
        {actions?.onClose && <Button iconOnly variant="ghost" size="sm" aria-label={labels.close} onClick={actions.onClose}><Close aria-hidden/></Button>}
      </div>
    </ContainerHeader>
    <ContainerBody>
      <div className="flex flex-wrap items-center gap-4">
        {scoreData ? <SecurityScore data={scoreData} scan={scan} labels={labels} locale={locale}/> : loading ? <Skeleton className="size-24 rounded-full"/> : <span className="flex size-24 shrink-0 items-center justify-center rounded-full border-hairline border-border text-heading text-fg-subtle">{labels.unknown}</span>}
        <div className="min-w-0 flex-1 basis-28"><p className="text-label text-fg-subtle">{labels.securityScore}</p><p className="mt-1 flex items-baseline gap-2"><span data-slot="security-score-value" className="text-heading font-semibold tabular-nums text-fg-default">{securityFormatNumber(currentScore, locale, 100)}</span><span className="text-body text-fg-subtle">/ 100</span></p><div className="mt-2 flex flex-wrap items-center gap-2">{delta !== null && <Badge size="sm" status={delta < 0 ? "danger" : delta > 0 ? "success" : "neutral"}>{delta > 0 ? "+" : ""}{securityFormatNumber(Math.abs(delta), locale)}{delta < 0 ? ` ${labels.points} ↓` : ` ${labels.points}`}</Badge>}<span className="text-label text-fg-subtle">{delta === null ? labels.unknown : `${labels.compare} · ${rangeLabels[range]}`}</span></div></div>
        {actions?.onRunScan && <div className="flex flex-col gap-1"><Button size="sm" leadingIcon={Shield} loading={scanning} disabled={Boolean(scanDisabledReason)} onClick={runScan}>{scanning ? labels.scanning : scan.status === "failed" ? labels.retry : labels.runScan}</Button>{scanDisabledReason && <p className="max-w-40 text-label text-fg-subtle">{scanDisabledReason}</p>}</div>}
      </div>
      <div className="mt-5 grid grid-cols-2 gap-2 @lg:grid-cols-4">
        <MetricCard label={labels.open} value={securityFormatNumber(total, locale)} state={metricState} content={{ type: "none" }} labelClassName="text-label" footer={scoreData?.openBySeverity && securityCountTotal(scoreData.openBySeverity) !== null ? <span className="text-fg-danger">{scoreData.openBySeverity.critical} {labels.critical}</span> : labels.unknown}/>
        <MetricCard label={labels.resolved} value={securityFormatCount(usable?.resolvedInWindow ?? null, locale)} state={metricState} content={{ type: "none" }} labelClassName="text-label" footer={rangeLabels[range]}/>
        <MetricCard label={labels.scannedAssets} value={securityFormatCount(scoreData?.scannedAssetCount ?? null, locale)} state={metricState} content={{ type: "none" }} labelClassName="text-label" footer={usable && securityValidCount(usable.newAssetsInWindow) ? `+${securityFormatCount(usable.newAssetsInWindow, locale)} · ${rangeLabels[range]}` : labels.unknown}/>
        <MetricCard label={labels.fixTime} value={securityFormatNumber(fixDays ? fixHours / 24 : fixHours, locale)} unit={fixDays ? labels.days : labels.hours} state={metricState} content={{ type: "none" }} labelClassName="text-label" footer={labels.median}/>
      </div>
    </ContainerBody>
    <Tabs value={activeView} variant="pill" color="default" onValueChange={(next) => { if (!views.includes(next as SecurityOverviewView))
        return; if (view === undefined)
        setLocalView(next as SecurityOverviewView); onViewChange?.(next as SecurityOverviewView); }} className="flex min-w-0 flex-col gap-2">
      <div className="overflow-x-auto"><TabsList aria-label={labels.navigation} className="w-full min-w-max">{views.map((item) => <TabItem key={item} value={item} label={labels[item]} className="flex-1 justify-center" badge={item === "findings" && total !== null ? total : item === "assets" && scoreData?.affectedAssetCount != null ? securityFormatCount(scoreData.affectedAssetCount, locale) : undefined}/>)}</TabsList></div>
      <TabPanel value={activeView}>
        <ContainerBody>
        {(state === "stale" || scanning || scan.status === "failed") && <div className="mb-4"><InlineNotice variant="emphasized" tone={scan.status === "failed" ? "danger" : "warning"}><InlineNoticeContent>{scan.status === "failed" ? scan.message : scanning ? labels.previousSnapshot : statusMessage ?? labels.stale}</InlineNoticeContent></InlineNotice></div>}
        {loading ? <div role="status" className="space-y-4"><span className="sr-only">{labels.loading}</span><Skeleton className="h-5 w-32"/><Skeleton className="h-48 w-full"/></div> : state === "error" ? <div className="flex min-w-0 w-full items-center justify-center min-h-60 px-4 py-8"><Alert status="danger" role="group" className="w-full max-w-xl"><AlertTitle>{statusMessage ?? labels.error}</AlertTitle><AlertAction>{actions?.onRetry && <Button variant="secondary" onClick={actions.onRetry}>{labels.retry}</Button>}</AlertAction></Alert></div> : viewProps ? activeView === "trend" ? <SecurityTrend {...viewProps}/> : activeView === "findings" ? <SecurityFindings {...viewProps}/> : activeView === "posture" ? <SecurityPosture {...viewProps}/> : <SecurityAssets {...viewProps}/> : <Empty reason="no-data" scope="inline"><EmptyDescription>{labels.noData}</EmptyDescription></Empty>}
        </ContainerBody>
      </TabPanel>
    </Tabs>
    <ContainerFooter className="justify-between gap-3">
      <div className="min-w-0 space-y-1"><p className="flex items-start gap-2 text-label text-fg-subtle"><Clock size={14} aria-hidden/><span>{scoped?.lastScanAt != null ? `${labels.lastScan} ${securityFormatDate(scoped.lastScanAt, locale, timeZone)}` : labels.neverScanned}</span></p><p role="status" aria-live="polite" className={cn("text-label", scan.status === "failed" ? "text-fg-danger" : "text-fg-muted")}>{scanText}</p>{exportState === "error" && <p role="alert" className="text-label text-fg-danger">{exportError ?? labels.exportError}</p>}</div>
      {actions?.onExport && <Button variant="secondary" size="sm" leadingIcon={Download} disabled={!usable} loading={exportState === "pending"} onClick={exportSnapshot}>{exportState === "pending" ? labels.exporting : labels.export}</Button>}
    </ContainerFooter>
  </Container>;
}

import type { ComponentPropsWithoutRef } from "react";
export type SecurityOverviewRange = "7d" | "30d" | "90d";
export type SecurityOverviewView = "trend" | "findings" | "posture" | "assets";
export type SecurityOverviewSeverity = "critical" | "high" | "medium" | "low";
export type SecurityOverviewCounts = Record<SecurityOverviewSeverity, number>;
export type SecurityOverviewState = "ready" | "loading" | "stale" | "error";
export interface SecurityOverviewFinding {
    id: string;
    title: string;
    assetId: string;
    assetName: string;
    severity: SecurityOverviewSeverity;
    /** Caller-supplied 0–10 score. Unknown is null. */
    score: number | null;
    detectedAt: number;
}
export interface SecurityOverviewAsset {
    id: string;
    name: string;
    kind: string;
    lastScannedAt: number | null;
    findings: SecurityOverviewCounts;
}
export interface SecurityOverviewPostureArea {
    id: string;
    label: string;
    score: number | null;
    previousScore: number | null;
}
export interface SecurityOverviewSnapshot {
    id: string;
    scopeId: string;
    range: SecurityOverviewRange;
    asOf: number;
    window: {
        start: number;
        end: number;
        comparisonAt: number;
    };
    score: number | null;
    grade: string | null;
    scoreTone: "success" | "warning" | "danger" | "neutral";
    previousScore: number | null;
    openBySeverity: SecurityOverviewCounts | null;
    resolvedInWindow: number | null;
    scannedAssetCount: number | null;
    newAssetsInWindow: number | null;
    affectedAssetCount: number | null;
    /** Server-aggregated median, in hours. */
    medianFixTimeHours: number | null;
    lastScanAt: number | null;
    /** Mutually exclusive severity counts at each instant. null is missing, not zero. */
    trend: readonly {
        at: number;
        counts: SecurityOverviewCounts | null;
    }[] | null;
    posture: readonly SecurityOverviewPostureArea[] | null;
    /** Sorted preview subset or full collection; lengths are not summary totals. */
    findings: readonly SecurityOverviewFinding[] | null;
    assets: readonly SecurityOverviewAsset[] | null;
}
export type SecurityOverviewScanState = {
    status: "idle";
} | {
    status: "starting";
} | {
    status: "running";
    jobId: string;
    completed: number | null;
    total: number | null;
} | {
    status: "refreshing";
    jobId: string;
} | {
    status: "succeeded";
    jobId: string;
    snapshotId: string;
    newFindingCount: number;
} | {
    status: "failed";
    jobId?: string;
    message: string;
};
export interface SecurityOverviewLabels {
    title: string;
    description: string;
    range: string;
    days7: string;
    days30: string;
    days90: string;
    trend: string;
    findings: string;
    posture: string;
    assets: string;
    navigation: string;
    securityScore: string;
    compare: string;
    points: string;
    open: string;
    resolved: string;
    scannedAssets: string;
    fixTime: string;
    median: string;
    days: string;
    hours: string;
    critical: string;
    high: string;
    medium: string;
    low: string;
    unknown: string;
    runScan: string;
    starting: string;
    scanning: string;
    refreshing: string;
    scanComplete: string;
    newFindings: string;
    previousSnapshot: string;
    progress: string;
    lastScan: string;
    neverScanned: string;
    export: string;
    exporting: string;
    exportError: string;
    close: string;
    retry: string;
    loading: string;
    error: string;
    stale: string;
    noData: string;
    noFindings: string;
    noAssets: string;
    trendDescription: string;
    total: string;
    viewValues: string;
    sortedByScore: string;
    viewAllFindings: string;
    viewAllAssets: string;
    affectedAssets: string;
    current: string;
    previous: string;
    postureDescription: string;
    change: string;
}
export interface SecurityOverviewProps extends Omit<ComponentPropsWithoutRef<"div">, "children" | "title" | "onChange" | "onClick"> {
    scopeId: string;
    data: SecurityOverviewSnapshot | null;
    state?: SecurityOverviewState;
    statusMessage?: string;
    range: SecurityOverviewRange;
    onRangeChange: (range: SecurityOverviewRange) => void;
    view?: SecurityOverviewView;
    defaultView?: SecurityOverviewView;
    onViewChange?: (view: SecurityOverviewView) => void;
    scan?: SecurityOverviewScanState;
    scanDisabledReason?: string;
    exportState?: "idle" | "pending" | "error";
    exportError?: string;
    actions?: {
        onRunScan?: (context: {
            scopeId: string;
        }) => void;
        onExport?: (context: {
            scopeId: string;
            snapshotId: string;
            range: SecurityOverviewRange;
        }) => void;
        onOpenFinding?: (id: string) => void;
        onOpenAsset?: (id: string) => void;
        onViewAll?: (kind: "findings" | "assets") => void;
        onRetry?: () => void;
        onClose?: () => void;
    };
    title?: string;
    description?: string;
    labels?: Partial<SecurityOverviewLabels>;
    locale?: string;
    timeZone?: string;
}

import type { BadgeColor } from "@ui/badge";
import type { SecurityOverviewCounts, SecurityOverviewFinding, SecurityOverviewLabels, SecurityOverviewSnapshot } from "./security-overview-types";
export const securitySeverities = ["critical", "high", "medium", "low"] as const;
export const securitySeverityColors = { critical: "red", high: "orange", medium: "amber", low: "gray" } as const satisfies Record<typeof securitySeverities[number], BadgeColor>;
export const securityOverviewLabels: SecurityOverviewLabels = {
    title: "安全概览", description: "评估当前安全状况，跟进风险与资产。", range: "统计时间范围",
    days7: "近 7 天", days30: "近 30 天", days90: "近 90 天",
    trend: "趋势", findings: "风险项", posture: "态势", assets: "资产", navigation: "安全概览视图",
    securityScore: "安全评分", compare: "较前期", points: "分", open: "未解决", resolved: "已解决",
    scannedAssets: "扫描资产", fixTime: "修复时间", median: "中位数", days: "天", hours: "小时",
    critical: "严重", high: "高风险", medium: "中风险", low: "低风险", unknown: "—",
    runScan: "开始扫描", starting: "正在启动", scanning: "扫描中", refreshing: "正在更新结果",
    scanComplete: "扫描完成", newFindings: "新增风险项", previousSnapshot: "展示上次扫描快照",
    progress: "已扫描", lastScan: "最近扫描", neverScanned: "暂无扫描记录",
    export: "导出报告", exporting: "正在导出", exportError: "导出失败，请重试", close: "关闭安全概览", retry: "重试",
    loading: "正在加载安全概览", error: "安全概览暂不可用", stale: "数据已过期，展示上次快照",
    noData: "暂无可用数据", noFindings: "当前没有未解决风险", noAssets: "当前没有受影响资产",
    trendDescription: "按风险级别展示未解决数量，面积为累计数量。", total: "合计", viewValues: "查看趋势数值",
    sortedByScore: "按评分降序", viewAllFindings: "查看全部风险项", viewAllAssets: "查看全部资产",
    affectedAssets: "受影响资产", current: "当前", previous: "前期", postureDescription: "各维度评分 · 满分 100", change: "变化",
};
export function securityValidNumber(value: unknown, max = Infinity): value is number {
    return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= max;
}
export function securityValidCount(value: unknown): value is number {
    return securityValidNumber(value) && Number.isSafeInteger(value);
}
export function securityValidTimestamp(value: unknown): value is number {
    return typeof value === "number" && Number.isFinite(value) && Math.abs(value) <= 8.64e15;
}
export function securityCountTotal(counts: SecurityOverviewCounts | null): number | null {
    if (!counts || securitySeverities.some((severity) => !securityValidCount(counts[severity])))
        return null;
    const total = securitySeverities.reduce((sum, severity) => sum + counts[severity], 0);
    return Number.isSafeInteger(total) ? total : null;
}
export function securityFormatNumber(value: number | null, locale: string, max = Infinity): string {
    return securityValidNumber(value, max) ? new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value) : "—";
}
export function securityFormatCount(value: number | null, locale: string): string {
    return securityValidCount(value) ? new Intl.NumberFormat(locale).format(value) : "—";
}
export function securityFormatDate(value: number | null, locale: string, timeZone: string): string {
    return securityValidTimestamp(value) ? new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit", timeZone }).format(value) : "—";
}
export function securitySortFindings(findings: readonly SecurityOverviewFinding[]): SecurityOverviewFinding[] {
    return [...findings].sort((a, b) => {
        const scoreA = securityValidNumber(a.score, 10) ? a.score : -1;
        const scoreB = securityValidNumber(b.score, 10) ? b.score : -1;
        const atA = securityValidTimestamp(a.detectedAt) ? a.detectedAt : -Infinity;
        const atB = securityValidTimestamp(b.detectedAt) ? b.detectedAt : -Infinity;
        return scoreB - scoreA || (atA === atB ? 0 : atB - atA) || a.id.localeCompare(b.id);
    });
}
export function securityTrendPoints(snapshot: SecurityOverviewSnapshot) {
    const { window, trend } = snapshot;
    if (!trend || !securityValidTimestamp(window.start) || !securityValidTimestamp(window.end) || window.end <= window.start)
        return null;
    if (trend.some((point, index) => !securityValidTimestamp(point.at) || point.at < window.start || point.at > window.end || (index > 0 && point.at <= trend[index - 1].at)))
        return null;
    return trend.map((point) => {
        const total = securityCountTotal(point.counts);
        return { at: point.at, total, critical: total === null ? null : point.counts!.critical,
            high: total === null ? null : point.counts!.high, medium: total === null ? null : point.counts!.medium,
            low: total === null ? null : point.counts!.low };
    });
}

"use client";
import { useId } from "react";
import { Area, AreaChart, CartesianGrid, PolarAngleAxis, PolarGrid, PolarRadiusAxis, Radar, RadarChart, XAxis, YAxis } from "recharts";
import { ChartContainer, ChartTooltip, ChartTooltipContent, DonutSummary, chartTrendPreset, type ChartConfig } from "@ui/chart";
import { ChartLegend, chartColor, chartStatusColors } from "@ui/chart-primitives";
import { badgeColors } from "@ui/badge";
import { Empty, EmptyDescription } from "@ui/empty";
import { securityFormatNumber, securitySeverities, securitySeverityColors, securityTrendPoints, securityValidNumber } from "./security-overview-data";
import type { SecurityOverviewLabels, SecurityOverviewScanState, SecurityOverviewSnapshot } from "./security-overview-types";
const scoreColors = { ...chartStatusColors, success: "var(--fg-brand)" };
const severityColors = Object.fromEntries(securitySeverities.map((severity) => [severity, badgeColors[securitySeverityColors[severity]]]));
export function SecurityScore({ data, scan, labels, locale }: {
    data: SecurityOverviewSnapshot;
    scan: SecurityOverviewScanState;
    labels: SecurityOverviewLabels;
    locale: string;
}) {
    const score = securityValidNumber(data.score, 100) ? data.score : null;
    const awaiting = scan.status === "succeeded" && scan.snapshotId !== data.id;
    const running = scan.status === "starting" || scan.status === "running" || scan.status === "refreshing" || awaiting;
    // The ring always describes the snapshot's score. Scan progress has its own existing notice.
    return <DonutSummary className="w-24 shrink-0" innerRadius="88%" total={100} segments={[{ id: "score", label: labels.securityScore, value: score, color: scoreColors[data.scoreTone] }]} aria-label={`${labels.securityScore} ${securityFormatNumber(score, locale, 100)} / 100${running ? ` · ${labels.previousSnapshot}` : ""}`} center={<span className="text-heading font-semibold">{score === null ? labels.unknown : data.grade ?? labels.unknown}</span>}/>;
}
export function SecurityTrend({ data, labels, locale, timeZone }: {
    data: SecurityOverviewSnapshot;
    labels: SecurityOverviewLabels;
    locale: string;
    timeZone: string;
}) {
    const gradientId = useId().replace(/:/g, "");
    const points = securityTrendPoints(data);
    const date = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", timeZone });
    const config: ChartConfig = Object.fromEntries(securitySeverities.map((severity) => [severity, { label: labels[severity], color: severityColors[severity] }]));
    if (!points?.length || points.every((point) => point.total === null))
        return <Empty reason="no-data" scope="inline"><EmptyDescription>{labels.noData}</EmptyDescription></Empty>;
    return <div className="space-y-4">
    <div className="flex flex-wrap items-start justify-between gap-3">
      <div><h3 className="text-body font-medium text-fg-default">{labels.open}</h3><p className="mt-1 text-label text-fg-subtle">{labels.trendDescription}</p></div>
      <ChartLegend className="flex flex-wrap gap-x-3 gap-y-1" items={securitySeverities.map((severity) => ({ id: severity, label: labels[severity], color: severityColors[severity] }))}/>
    </div>
    <ChartContainer className="h-48" config={config} aria-label={labels.trendDescription}>
      <AreaChart data={points} accessibilityLayer margin={chartTrendPreset.margin}>
